#include "memory_diagnostics.hpp"
#include "r6_cli.hpp"
#include "wire.hpp"
#include <iostream>
using namespace zkgpt;
int main(int argc,char**argv){try{r1::require(argc>=4,"usage: r6_model_prove NEW_DIR --blocks1|12 --trusted-anchor FILE --anchor-sha256 HEX --model-manifest FILE [--plan-only]");auto o=r6::options(argc,argv,2);if(o.plan_only){r1::init();r6::plan(argv[1],o);std::cout<<"PASS R6 plan-only,no private witness/proof\n";return 0;}r6::requireExecution(o);r6::limits(o,false);r1::init();r1::require(!std::filesystem::exists(argv[1]),"R6 output directory exists");
 r5b::Anchor anchor;std::string fingerprint;r6::Resources budgets;std::size_t planned_actual=0;
 {LLM pub(o.blocks,12,64,768,3072);r6::configure(pub);auto c=pub.buildPublicCircuit();auto p=r2::planModelQueries(c,pub.getWitnessRegistry(),pub.parameterRegions(),r1::ExpProfile::LegacyClampOne);r6::auditGraph(c,pub,p);anchor=r6::loadAnchor(o.anchor,o.pin,o.manifest,p);planned_actual=p.master.actual;zkgpt::memory_diagnostics::logAddress("preflight/graph","object",&c,0,"scoped-preflight");zkgpt::memory_diagnostics::logAddress("preflight/graph","layers",c.circuit.data(),c.circuit.capacity()*sizeof(layer),"scoped-preflight");budgets=r6::resources(c,pub,p);r6::preflight(o,budgets,p,"prover");fingerprint=p.circuit_id;}
 zkgpt::memory_diagnostics::logScalar("preflight/graph-destroyed","live_preflight_graphs",0);
 r5b::newDirectory(argv[1]);const std::filesystem::path dir=argv[1];auto mb=r1::readFile(o.manifest);auto manifest=r6::parseManifest(mb,o.blocks);r6::checkParameterFiles(manifest,"data/gpt2_int");LLM nn(o.blocks,12,64,768,3072);r6::configure(nn);nn.setWitnessCapacityHint(planned_actual);prover pr{};nn.create(pr,false);nn.validateCurrentWitness(pr);r6::checkParameterFiles(manifest,"data/gpt2_int");
 auto p=r2::planModelQueries(pr.C,nn.getWitnessRegistry(),nn.parameterRegions(),r1::ExpProfile::LegacyClampOne);r1::require(p.circuit_id==fingerprint,"R6 private/public circuit mismatch");r6::validateRegions(p,nn.parameterRegions());auto start=std::chrono::steady_clock::now();auto progress=[&](const std::string&s){r6::runtimeCheck(o);std::cerr<<"PHASE "<<s<<" seconds="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<std::endl;};
 const auto&master=pr.sharedInputWitness();
 zkgpt::memory_diagnostics::logAddress("caller/master-ref","caller_master",master.data(),master.capacity()*sizeof(Fr),"prover.vector/const-ref");
 zkgpt::memory_diagnostics::logAddress("caller/master-ref","val0",pr.val[0].data(),pr.val[0].capacity()*sizeof(Fr),"prover.val0");
 zkgpt::memory_diagnostics::logAddress("caller/master-ref","actual_graph",&pr.C,0,"prover.C");
auto v=r2::gatherModelQueries(p,master);auto cm=r1::commit(p.master,master);std::vector<r1::Commitment>cs;for(std::size_t i=0;i<v.size();++i){r6::runtimeCheck(o);cs.push_back(r1::commit(p.sources[i].spec,v[i]));}r5b::requireAnchorW(anchor,cs.back());std::vector<Fr>x(master.begin(),master.begin()+32768),y;for(auto i:p.output)y.push_back(master[i]);auto s=r2::makeModelQueryStatement(p,cm,cs,anchor.w,x,y,anchor.model_id);r2::requireModelQueryStatement(p,s,anchor.w,x,y,anchor.model_id);
 GKRPublicStatement g;g.model_shape=p.shape;g.val0_log_size=pr.cc.l;g.val0_commitment.assign(pr.cc.comm,pr.cc.comm+(std::size_t(1)<<(pr.cc.l/2)));g.val0_generator_domain={"zkGPT/main",std::uint32_t(std::size_t(1)<<(pr.cc.l-pr.cc.l/2))};g.circuit_fingerprint=fingerprintCircuit(pr.C);g.output_evaluation=Fr(0);auto proof=r2::proveR2(pr,g,s,master,v,progress);r1::writeFile((dir/"model.statement").string(),r2::serializeStatement(g,s));r1::writeFile((dir/"model.proof").string(),r2::serializeProof(g,s,proof));std::cout<<"GENERATED R6 blocks="<<o.blocks<<"; independent verification required; OPERATOR-TRUSTED candidate only\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
